/**
 * Per-member project mutes: which projects a member has silenced.
 */
import { and, eq, inArray } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** Idempotent: muting an already-muted project changes nothing. */
export async function insertMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      userId,
      projectId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();
}

/** Idempotent: unmuting a project that is not muted changes nothing. */
export async function deleteMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .run();
}

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Which of `userIds` have muted `projectId` — the fan-out's one lookup. */
export async function listUsersMutingProject(
  orgId: OrgId,
  projectId: ProjectId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
        inArray(projectMutes.userId, [...userIds]),
      ),
    )
    .all();
  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

/** The digest's filter: which of this recipient's projects are muted. */
export async function listMutedProjectIdsFor(
  orgId: OrgId,
  userId: UserId,
): Promise<ReadonlySet<ProjectId>> {
  return new Set(await listMutedProjectIds(orgId, userId));
}
